prodSchema:
(tpl)=>({
  name: ('CF '+tpl.label+' PDP').substring(0,25).trimEnd(),
  settings: s.PRODUCT_SETTINGS.map(x=>{
    const o={...x};
    if(o.id==='color_accent') o.default=tpl.accent;
    if(o.id==='color_bg') o.default=tpl.bg;
    return o;
  }),
  presets:[{name:('CF '+tpl.label+' PDP').substring(0,25).trimEnd()}]
})

